const CACHE='tokyo-station-walk-v5';
const FILES=['./','./index.html','./style.css','./guide-ui.css?v=5','./app.js?v=5','./scene.js','./station-layout.js','./station-map.js','./floor-layout.js','./building-scene.js?v=5','./train-data.js?v=5','./train-scene.js?v=5','./station-guide-data.js','./gate-visuals.js','./vendor/three.module.js','./icon.svg','./icon-180.png','./icon-192.png','./icon-512.png','./manifest.webmanifest'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES.map(path=>new Request(path,{cache:'reload'})))).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('tokyo-station-walk-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request,{cache:'no-cache'}).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy))}return response}).catch(()=>caches.match(event.request).then(hit=>hit||new Response('オフラインで利用するには、初回にオンラインで開いてください。',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}}))))});
